 const syncLegacyOffers=()=>{try{const raw=localStorage.getItem('incentives_engine_offers');if(!raw)return;const parsed=JSON.parse(raw);if(!Array.isArray(parsed))return;const demoIds=new Set(['offer-happy-hour','offer-burger-combo','offer-pizza-bogo','offer-new-customer','offer-wings-weekend','offer-test-draft']);const legacy=parsed.filter(offer=>!demoIds.has(offer.id));setState(previous=>{const mapped=legacy.map(offer=>legacyOfferToDiscount(offer,previous.items)).filter(Boolean) as Discount[];const mappedIds=new Set(mapped.map(discount=>discount.id));const cart=previous.cart.filter(line=>!line.autoRewardDiscountId||mappedIds.has(line.autoRewardDiscountId));const now=Date.now();const shouldAdvanceClock=mapped.some(discount=>discount.isActive&&discount.startAt&&new Date(discount.startAt).getTime()<=now&&new Date(previous.settings.simulatedAt).getTime()<new Date(discount.startAt).getTime());return {...previous,discounts:mapped,cart,settings:shouldAdvanceClock?{...previous.settings,simulatedAt:new Date(now).toISOString()}:previous.settings}})}catch{}}
