    <Card className="overflow-hidden"><CardHeader className="border-b bg-muted/30"><div className="flex flex-wrap items-start justify-between gap-3"><div><CardTitle className="text-base">Build a basket</CardTitle><CardDescription>Try automatic offers and coupon codes against a realistic order.</CardDescription></div><div className="flex gap-2"><select className="h-9 rounded-md border bg-background px-3 text-sm" value={state.selectedLocation} onChange={e=>setState(s=>({...s,selectedLocation:e.target.value}))}>{state.locations.map(l=><option key={l.id} value={l.id}>{l.name}</option>)}</select><select className="h-9 rounded-md border bg-background px-3 text-sm" value={state.selectedCustomer} onChange={e=>setState(s=>({...s,selectedCustomer:e.target.value}))}>{state.customers.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></div></div><div className="flex flex-wrap gap-2 pt-2"><div className="relative min-w-48 flex-1"><Search className="absolute left-3 top-2.5 h-4 w-4 text-muted-foreground"/><Input className="pl-9" placeholder="Search menu" value={search} onChange={e=>setSearch(e.target.value)}/></div><select className="h-10 rounded-md border bg-background px-3 text-sm" value={category} onChange={e=>setCategory(e.target.value)}><option>All</option>{state.categories.map(c=><option key={c}>{c}</option>)}</select><select className="h-10 rounded-md border bg-background px-3 text-sm" value={orderType} onChange={e=>setOrderType(e.target.value as any)}><option value="PICKUP">Pickup</option><option value="DELIVERY">Delivery</option></select></div></CardHeader><CardContent className="grid gap-3 p-4 sm:grid-cols-2 lg:grid-cols-3">{filteredItems.map(item=><button key={item.id} onClick={()=>addItem(item.id)} className="group flex h-full flex-col rounded-xl border bg-card p-3 text-left transition hover:border-primary/40 hover:shadow-md"><div className="relative mb-3 w-full overflow-hidden rounded-lg bg-muted"><img src={menuImage(item)} alt="" className="h-32 w-full object-cover transition duration-300 group-hover:scale-[1.02]" onError={event=>{event.currentTarget.onerror=null;event.currentTarget.src=fallbackMenuImage(item.category)}}/>{item.promotionOffers?.length? <span title={item.promotionOffers[0].name} className="absolute left-2 top-2 flex max-w-[calc(100%-3.5rem)] items-center gap-1.5 truncate rounded-full bg-rose-600 px-2.5 py-1 text-[11px] font-bold text-white shadow"><Tag className="h-3 w-3 shrink-0"/>{item.promotionOffers[0].label||item.promotionOffers[0].name}</span>:null}<span className="absolute right-2 top-2 grid h-8 w-8 place-items-center rounded-full bg-background/90 text-primary shadow-sm"><Plus className="h-4 w-4 transition group-hover:scale-110"/></span></div><div className="w-full"><p className="line-clamp-2 min-h-10 font-semibold">{item.name}</p><p className="mt-1 text-xs text-muted-foreground">{item.category} · {item.stock} in stock</p><div className="mt-3 flex items-end justify-between gap-2"><p className="text-sm font-bold">{cash(item.price,state.settings.currency)}</p>{item.promotionOffers&&item.promotionOffers.length>1&&<span className="shrink-0 text-[11px] font-medium text-rose-700">+{item.promotionOffers.length-1} more offer{item.promotionOffers.length===2?'':'s'}</span>}</div>{item.promotionOffers?.[0]?.isConditional&&<p className="mt-1 text-[11px] text-rose-700">Conditions apply</p>}</div></button>)}{!filteredItems.length&&<p className="col-span-full p-8 text-center text-sm text-muted-foreground">No available products match this search.</p>}</CardContent></Card>
    
